/**
The characters `String.prototype.trim()` removes, which is the ECMAScript `WhiteSpace` production plus the byte order mark. It is deliberately not the Unicode `White_Space` property: `U+0085` (NEL) is a control character there, and JavaScript keeps it.
*/
export type Whitespace =
	| '\u{9}' // '\t'
	| '\u{A}' // '\n'
	| '\u{B}' // '\v'
	| '\u{C}' // '\f'
	| '\u{D}' // '\r'
	| '\u{20}' // ' '
	| '\u{A0}'
	| '\u{1680}'
	| '\u{2000}'
	| '\u{2001}'
	| '\u{2002}'
	| '\u{2003}'
	| '\u{2004}'
	| '\u{2005}'
	| '\u{2006}'
	| '\u{2007}'
	| '\u{2008}'
	| '\u{2009}'
	| '\u{200A}'
	| '\u{2028}'
	| '\u{2029}'
	| '\u{202F}'
	| '\u{205F}'
	| '\u{3000}'
	| '\u{FEFF}';

// `U+0085` (next line) is not whitespace to `String.prototype.trim()`, but it still separates words.
export type WordSeparators = '-' | '_' | '\u{85}' | Whitespace;

export type AsciiPunctuation =
	| '!'
	| '"'
	| '#'
	| '$'
	| '%'
	| '&'
	| '\''
	| '('
	| ')'
	| '*'
	| '+'
	| ','
	| '-'
	| '.'
	| '/'
	| ':'
	| ';'
	| '<'
	| '='
	| '>'
	| '?'
	| '@'
	| '['
	| '\\'
	| ']'
	| '^'
	| '_'
	| '`'
	| '{'
	| '|'
	| '}'
	| '~';

/**
The characters of the Unicode titlecase category (`Lt`), which is closed at these 31 code points. Each is changed by both lowercasing and uppercasing, so a character like `ǅ` is neither lowercase nor uppercase, though it also matches none of the uppercase or lowercase shapes the case predicates look for.
*/
export type TitlecaseCharacter =
	| '\u{1C5}'
	| '\u{1C8}'
	| '\u{1CB}'
	| '\u{1F2}'
	| '\u{1F88}'
	| '\u{1F89}'
	| '\u{1F8A}'
	| '\u{1F8B}'
	| '\u{1F8C}'
	| '\u{1F8D}'
	| '\u{1F8E}'
	| '\u{1F8F}'
	| '\u{1F98}'
	| '\u{1F99}'
	| '\u{1F9A}'
	| '\u{1F9B}'
	| '\u{1F9C}'
	| '\u{1F9D}'
	| '\u{1F9E}'
	| '\u{1F9F}'
	| '\u{1FA8}'
	| '\u{1FA9}'
	| '\u{1FAA}'
	| '\u{1FAB}'
	| '\u{1FAC}'
	| '\u{1FAD}'
	| '\u{1FAE}'
	| '\u{1FAF}'
	| '\u{1FBC}'
	| '\u{1FCC}'
	| '\u{1FFC}';

export {};
